// `pnpm --filter @lumiose/web ui:demos`.
import { DeleteProject } from "./dialog-1.tsx";
import { EditProfile } from "./dialog-2.tsx";
import { ProjectMenu } from "./menu-1.tsx";
import { Notifications } from "./popover-1.tsx";
import { Filters } from "./popover-2.tsx";
import { AccountSettings } from "./tabs-1.tsx";
import { Project } from "./tabs-2.tsx";
import { BoldButton } from "./tooltip-1.tsx";

/** A demo by id: server HTML, or an island that hydrates when it scrolls into view. */
export function UiDemo(props: { id: string }) {
  switch (props.id) {
    case "dialog-1":
      return <DeleteProject />;
    case "dialog-2":
      return <EditProfile client:visible />;
    case "menu-1":
      return <ProjectMenu />;
    case "popover-1":
      return <Notifications />;
    case "popover-2":
      return <Filters client:visible />;
    case "tabs-1":
      return <AccountSettings />;
    case "tabs-2":
      return <Project client:visible />;
    case "tooltip-1":
      return <BoldButton />;
    default:
      throw new Error(`No UI demo "${props.id}": run pnpm --filter @lumiose/web ui:demos.`);
  }
}
